/**
 * Styling mandiri modul — kelas ber-prefix `spine-sts` yang memakai
 * CSS var token theme host (--surface, --ink, dll.). Bundle di-load runtime
 * tanpa ikut scanner Tailwind host, jadi modul tidak boleh bergantung pada
 * utility class Tailwind yang mungkin tidak dibangkitkan.
 */

const CSS = `
.spine-sts-card {
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  background: var(--surface-raised);
  padding: 12px 14px;
  color: var(--ink);
}
.spine-sts-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 8px;
}
.spine-sts-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.spine-sts-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 13px;
}
.spine-sts-muted {
  color: var(--ink-muted);
}
.spine-sts-badge {
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 11px;
  font-weight: 500;
  background: var(--accent-soft);
  color: var(--accent-strong);
}
.spine-sts-empty {
  font-size: 13px;
  color: var(--ink-faint);
}
.spine-sts-link {
  color: var(--accent-strong);
  font-size: 12px;
  text-decoration: none;
}
.spine-sts-grid {
  display: flex;
  gap: 8px;
}
.spine-sts-pill {
  flex: 1;
  text-align: center;
  border-radius: 10px;
  padding: 6px 4px;
  background: var(--surface-overlay);
}
.spine-sts-pill b {
  display: block;
  font-size: 16px;
  color: var(--ink);
}
.spine-sts-pill span {
  font-size: 11px;
  color: var(--ink-muted);
}
`;

let injected = false;
export function ensureModuleStyles() {
  if (injected || typeof document === "undefined") return;
  injected = true;
  const el = document.createElement("style");
  el.textContent = CSS;
  document.head.appendChild(el);
}