/**
 * Shim React — bundle modul memakai SATU instance React dari host
 * (`globalThis.__SPINE__.react`), bukan salinan sendiri. Tanpa ini hook
 * modul tidak tersambung ke reconciler host (masalah "dua React").
 *
 * esbuild `--alias:react=./src/shims/react.ts` mengarahkan semua impor
 * `react` di modul ke file ini — yang hanya re-export dari global host.
 */
type ReactType = typeof import("react");

const g = globalThis as { __SPINE__?: { react?: unknown } };
const R = g.__SPINE__?.react as unknown as ReactType;

export default R;
export const useState = R.useState;
export const useEffect = R.useEffect;
export const useCallback = R.useCallback;
export const useMemo = R.useMemo;
export const useRef = R.useRef;
export const createElement = R.createElement;
export const createContext = R.createContext;
export const useContext = R.useContext;
export const Fragment = R.Fragment;
export const lazy = R.lazy;
export const Suspense = R.Suspense;
export const Children = R.Children;
export const isValidElement = R.isValidElement;
export const memo = R.memo;
export const forwardRef = R.forwardRef;