import {
  SampleTasksSummary,
  SampleTasksTab,
  SampleTasksWidget,
} from "./components";
import type { ModuleContext, SpineModule } from "./types";

/**
 * Module frontend "sampletasks" — pendamping modul backend dengan nama sama.
 * Contoh cara modul eksternal menyumbang UI ke area core tanpa mengubah kode
 * core: register context.ui.* dengan komponen milik sendiri.
 */
const module: SpineModule = {
  id: "sample-tasks",
  name: "SampleTasks UI",
  version: "0.1.0",

  translations: {
    en: {
      "tabs.sampleTasks": "Sample Tasks",
      "sections.summary": "Sample Tasks Summary",
      "widgets.quickStats": "Sample Tasks — quick stats",
    },
    id: {
      "tabs.sampleTasks": "Tugas Contoh",
      "sections.summary": "Ringkasan Tugas Contoh",
      "widgets.quickStats": "Tugas Contoh — statistik cepat",
    },
  },

  register(ctx: ModuleContext) {
    const { module, i18n, ui } = ctx;

    // Terjemahan milik modul — core hanya resolve label (i18n.addTranslations).
    i18n.addTranslations("module." + module.id, {
      "tabs.sampleTasks": "Sample Tasks",
      "sections.summary": "Sample Tasks Summary",
      "widgets.quickStats": "Sample Tasks — quick stats",
    });

    ui.tabs.register({
      area: "profile.tabs",
      id: "sample-tasks",
      label: { namespace: "module." + module.id, key: "tabs.sampleTasks" },
      icon: "✅",
      position: 30,
      module: module.id,
      component: SampleTasksTab,
    });

    ui.sections.register({
      area: "profile.sections",
      id: "sampletasks-summary",
      label: { namespace: "module." + module.id, key: "sections.summary" },
      position: 40,
      module: module.id,
      component: SampleTasksSummary,
    });

    ui.sections.register({
      area: "dashboard.widgets",
      id: "sampletasks-stats",
      label: { namespace: "module." + module.id, key: "widgets.quickStats" },
      position: 20,
      module: module.id,
      component: SampleTasksWidget,
    });
  },
};

export default module;