/**
 * Helper API mandiri untuk modul — tidak impor core (`@/lib/api`).
 * Base URL dibaca dari global host (`__SPINE__.apiBase`), token dari
 * `localStorage.spine_token` (key yang sama dengan core).
 */

function baseUrl(): string {
  const host = (globalThis as { __SPINE__?: { apiBase?: string } }).__SPINE__;
  return host?.apiBase ?? "http://localhost:8000";
}

export function getToken(): string | null {
  if (typeof window === "undefined") return null;
  return window.localStorage.getItem("spine_token");
}

export interface ApiResult<T> {
  ok: boolean;
  status: number;
  data: T;
  error?: string;
}

export async function api<T = unknown>(
  path: string,
  options: RequestInit = {}
): Promise<ApiResult<T>> {
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...(options.body ? { "Content-Type": "application/json" } : {}),
  };
  const token = getToken();
  if (token) headers.Authorization = `Bearer ${token}`;

  const res = await fetch(`${baseUrl()}${path}`, { ...options, headers });

  let data: unknown = null;
  try {
    data = await res.json();
  } catch {
    // body kosong
  }

  if (!res.ok) {
    const err = (data as { message?: string })?.message ?? `HTTP ${res.status}`;
    return { ok: false, status: res.status, data: data as T, error: err };
  }

  return { ok: true, status: res.status, data: data as T };
}