import { Fragment, useCallback, useEffect, useState } from "react";
import { api } from "./api";
import { ensureModuleStyles } from "./styles";

/**
 * Komponen demo modul SampleTasks — semua mandiri (zero impor core).
 * React diambil dari host via shim (`src/shims/react.ts`), styling pakai
 * token CSS var host lewat `src/styles.ts`.
 */

interface SampleTask {
  id: number;
  sample_item_id: number;
  title: string;
  status: string;
  created_at?: string;
}

const STATUSES = ["pending", "in_progress", "done"] as const;

function statusColor(status: string): string {
  if (status === "done") return "var(--success)";
  if (status === "in_progress") return "var(--warning)";
  return "var(--info)";
}

function TaskBadge({ status }: { status: string }) {
  return (
    <span
      style={{
        borderRadius: 999,
        padding: "1px 8px",
        fontSize: 11,
        fontWeight: 500,
        color: statusColor(status),
        border: `1px solid ${statusColor(status)}`,
      }}
    >
      {status.replace("_", " ")}
    </span>
  );
}

function useSampleTasks() {
  const [items, setItems] = useState<SampleTask[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(() => {
    api<{ data: SampleTask[] }>("/api/v1/sample-tasks")
      .then((res) => {
        if (res.ok) setItems(res.data?.data ?? []);
        else setError(res.error ?? "Gagal memuat");
      })
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function markStatus(task: SampleTask, status: string) {
    if (task.status === status) return;
    const res = await api(`/api/v1/sample-tasks/${task.id}`, {
      method: "PUT",
      body: JSON.stringify({ status }),
    });
    if (!res.ok) {
      setError(res.error ?? "Gagal mengubah status");
      return;
    }
    setItems((prev) =>
      prev.map((t) => (t.id === task.id ? { ...t, status } : t))
    );
  }

  return { items, loading, error, markStatus, reload: load };
}

function CountPills({ items }: { items: SampleTask[] }) {
  const count = (s: string) => items.filter((t) => t.status === s).length;
  return (
    <div className="spine-sts-grid" style={{ marginBottom: 10 }}>
      {STATUSES.map((s) => (
        <div key={s} className="spine-sts-pill">
          <b>{count(s)}</b>
          <span>{s.replace("_", " ")}</span>
        </div>
      ))}
    </div>
  );
}

/** Widget dashboard — ringkasan + 3 task terbaru (area dashboard.widgets). */
export function SampleTasksWidget() {
  ensureModuleStyles();
  const { items, loading, error } = useSampleTasks();

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample Task — ringkasan</h3>
      {error && <div className="spine-sts-muted">{error}</div>}
      {loading ? (
        <div className="spine-sts-empty">Memuat...</div>
      ) : (
        <Fragment>
          <CountPills items={items} />
          <ul className="spine-sts-list">
            {items.slice(0, 3).map((t) => (
              <li key={t.id} className="spine-sts-item">
                <span className="spine-sts-muted">#{t.id} — {t.title}</span>
                <TaskBadge status={t.status} />
              </li>
            ))}
          </ul>
        </Fragment>
      )}
    </div>
  );
}

/** Tab profil — daftar task + tombol ubah status (area profile.tabs). */
export function SampleTasksTab() {
  ensureModuleStyles();
  const { items, loading, error, markStatus } = useSampleTasks();

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample Tasks</h3>
      {error && <div className="spine-sts-muted">{error}</div>}
      {loading ? (
        <div className="spine-sts-empty">Memuat...</div>
      ) : items.length === 0 ? (
        <div className="spine-sts-empty">Belum ada task.</div>
      ) : (
        <ul className="spine-sts-list">
          {items.map((t) => (
            <li key={t.id} className="spine-sts-item">
              <span>
                <span className="spine-sts-muted">#{t.id}</span>{" "}
                <span>{t.title}</span>
              </span>
              <span style={{ display: "inline-flex", gap: 6, alignItems: "center" }}>
                <TaskBadge status={t.status} />
                {t.status !== "done" && (
                  <button
                    type="button"
                    onClick={() => markStatus(t, "done")}
                    style={{
                      border: "1px solid var(--line)",
                      borderRadius: 8,
                      background: "transparent",
                      color: "var(--accent-strong)",
                      fontSize: 12,
                      cursor: "pointer",
                      padding: "2px 8px",
                    }}
                  >
                    Selesai
                  </button>
                )}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** Section profil — ringkas: total + hasil (area profile.sections). */
export function SampleTasksSummary() {
  ensureModuleStyles();
  const { items, loading } = useSampleTasks();

  if (loading) return null;
  const done = items.filter((t) => t.status === "done").length;
  const donePct = items.length ? Math.round((done / items.length) * 100) : 0;

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample Tasks</h3>
      <p className="spine-sts-muted" style={{ margin: 0 }}>
        Total <b>{items.length}</b> task, <b>{done}</b> selesai ({donePct}%).
      </p>
      <a className="spine-sts-link" href="/sample-tasks">
        Buka Sample Tasks →
      </a>
    </div>
  );
}